xt":"Σ║åΦºúµêæΣ╗¼τÜäµòàΣ║ï","btn1_link":"aboutus/index.html","btn2_text":"Θóäτ║ªσÆ¿Φ»ó","btn2_link":"contact/index.html"}},"services":{"badge":"FEATURED PATHWAYS","heading":"Our Services \\\\u0026amp;","heading_italic":"Pathways","description":"Sovereign dual citizenship, European golden visas, Dubai luxury property portfolios, and Ivy League academic guidance.","pillar_cbi":{"pillar_badge":"Pillar 01 ΓÇó Passports","title":"Citizenship by Investment","p1":"Getting a second citizenship gives you and your family the legal right to hold an extra passport. This opens up doors for easy global travel without needing visas ahead of time.","p2":"Our team handles all paperwork, background checks, and official submissions so you do not have to worry about complicated rules.","items":[{"id":"dominica","title":"Dominica | Passport","desc":"Safe and peaceful Caribbean island offering straightforward legal passport processing without travel or language tests.","link":"programs/citizenshipbyinvestment/dominica/index.html"},{"id":"stkitts","title":"St. Kitts \\\\u0026amp; Nevis | Passport","desc":"The oldest and most trusted citizenship by investment program in the world, active since 1984 with dependable asset security.","link":"programs/citizenshipbyinvestment/stkittis/index.html"},{"id":"antigua","title":"Antigua \\\\u0026amp; Barbuda | Passport","desc":"The best and most cost-effective passport solution for large families, covering up to four members under one baseline fee.","link":"programs/citizenshipbyinvestment/antiguaandbarbuda/index.html"},{"id":"lucia","title":"Saint Lucia | Passport","desc":"Flexible financial options with government-guaranteed bond investments that are 100% refundable after 5 years.","link":"programs/citizenshipbyinvestment/stlucia/index.html"},{"id":"grenada","title":"Grenada | Passport","desc":"Powerful second passport providing direct qualification to apply for the USA E-2 Investor Visa to live and conduct business in America.","link":"programs/cit