INSERT INTO cms_content (content_key, draft_data, live_data, updated_at, published_at) VALUES
('sgcms_aboutus', '{"hero":{"en":{"badge":"EXECUTIVE BRIEFING","title":"About Sharif Group","subtitle":"A premier migration, citizenship, and luxury investment advisory platform rooted in Business Bay, Dubai.","img":"https://sharifgroup.ae/wp-content/uploads/2026/05/dubai-office-2.jpg.webp"}},"overview":{"en":{"badge":"WHO WE ARE","heading":"Company Overview: Sharif Group","p1":"Sharif Group is a dedicated private consulting company based in Business Bay, Dubai. We assist international clients and families with legal second passports, residency visas, premium property investments, and student placements in top international universities.","p2":"Our team handles document preparation, background legal checks, and government clearance from start to finish, ensuring a straightforward and secure experience.","cta_text":"Book Consultation","cta_link":"../contact/index.html"}},"stats":[{"value":"10+","label_en":"Years of Experience"},{"value":"1000+","label_en":"Successful CBI Cases"},{"value":"100+","label_en":"Residency \\\\u0026amp; Education Cases"},{"value":"450+","label_en":"Families Relocated"}],"architecture":{"en":{"badge":"CORPORATE ARCHITECTURE","title":"Three Companies. One Commitment.","desc":"We structure our specialized operations under three dedicated corporate brands to deliver clean, transparent, and expert execution across every discipline.","c1_name":"SHARIF GLOBAL DOCUMENTS CLEARING SERVICES L.L.C","c1_badge":"Citizenship \\\\u0026amp; Residency","c1_p1":"Sharif Global helps families and investors get legal second passports and European residency cards. We handle all paperwork smoothly, check your documents carefully, and deal directly with government authorities.","c1_p2":"We also guide your children with student admissions to top international schools and world-renowned universities abroad. Our team manages the legal attestation, translation, and complete file submissions.","c2_name":"SHARIF STAR REAL ESTATE BROKER L.L.C","c2_badge":"Real Estate Brokerage","c2_p1":"Sharif Star is our official licensed real estate agency helping local and foreign buyers find premium homes across Dubai. We find luxury villas, high-floor apartments, and profitable off-plan projects in top neighborhoods.","c2_p2":"We also structure high-value property purchases that qualify you directly for the 10-Year UAE Golden Visa. Our real estate brokers assist you through contract signing, title deed registration, and ongoing leasing.","c3_name":"SHARIF CAPITAL COMMERCIAL BROKERS L.L.C","c3_badge":"Capital \\\\u0026amp; Brokerage","c3_p1":"Sharif Capital is our specialized business brokerage branch connecting entrepreneurs and serious investors with solid commercial opportunities in Dubai and the GCC region.","c3_p2":"We also help global business owners set up new companies, open corporate bank accounts, and structure joint business ventures with complete confidentiality."}},"founder":{"en":{"name":"Ali Sharif","title":"CEO \\\\u0026amp; Founder, Sharif Group","badge":"A MESSAGE FROM OUR FOUNDER","quote":"A future where happy clients, positive community impact, and continuous progress guide everything we do.","p1":"As the founder of Sharif Group, I, Ali Sharif, started this journey with a clear goal: to build real value for our clients and trusted partners. Today, with our hard-working team, we are proud to set high standards in second citizenship and global investment advisory.","p2":"Over the past few years, our growth has been driven by honest effort and commitment. We have expanded our reach internationally, opening dedicated office hubs in both Dubai and London to serve our clients seamlessly.","photo":"alisharif.webp","profile_link":"https://sharifgroup.ae/ali-sharif/"}},"cta":{"en":{"badge":"EXECUTIVE ADVISORY DESK","heading":"Schedule Your Expert Consultation Today","desc":"Connect directly with our registered advisors at 116, The Binary Tower, Business Bay, Dubai to initialize your pre-vetting sequence.","btn_text":"Request Executive Briefing","btn_link":"../contact/index.html"}}}', '{"hero":{"en":{"badge":"EXECUTIVE BRIEFING","title":"About Sharif Group","subtitle":"A premier migration, citizenship, and luxury investment advisory platform rooted in Business Bay, Dubai.","img":"https://sharifgroup.ae/wp-content/uploads/2026/05/dubai-office-2.jpg.webp"}},"overview":{"en":{"badge":"WHO WE ARE","heading":"Company Overview: Sharif Group","p1":"Sharif Group is a dedicated private consulting company based in Business Bay, Dubai. We assist international clients and families with legal second passports, residency visas, premium property investments, and student placements in top international universities.","p2":"Our team handles document preparation, background legal checks, and government clearance from start to finish, ensuring a straightforward and secure experience.","cta_text":"Book Consultation","cta_link":"../contact/index.html"}},"stats":[{"value":"10+","label_en":"Years of Experience"},{"value":"1000+","label_en":"Successful CBI Cases"},{"value":"100+","label_en":"Residency \\\\u0026amp; Education Cases"},{"value":"450+","label_en":"Families Relocated"}],"architecture":{"en":{"badge":"CORPORATE ARCHITECTURE","title":"Three Companies. One Commitment.","desc":"We structure our specialized operations under three dedicated corporate brands to deliver clean, transparent, and expert execution across every discipline.","c1_name":"SHARIF GLOBAL DOCUMENTS CLEARING SERVICES L.L.C","c1_badge":"Citizenship \\\\u0026amp; Residency","c1_p1":"Sharif Global helps families and investors get legal second passports and European residency cards. We handle all paperwork smoothly, check your documents carefully, and deal directly with government authorities.","c1_p2":"We also guide your children with student admissions to top international schools and world-renowned universities abroad. Our team manages the legal attestation, translation, and complete file submissions.","c2_name":"SHARIF STAR REAL ESTATE BROKER L.L.C","c2_badge":"Real Estate Brokerage","c2_p1":"Sharif Star is our official licensed real estate agency helping local and foreign buyers find premium homes across Dubai. We find luxury villas, high-floor apartments, and profitable off-plan projects in top neighborhoods.","c2_p2":"We also structure high-value property purchases that qualify you directly for the 10-Year UAE Golden Visa. Our real estate brokers assist you through contract signing, title deed registration, and ongoing leasing.","c3_name":"SHARIF CAPITAL COMMERCIAL BROKERS L.L.C","c3_badge":"Capital \\\\u0026amp; Brokerage","c3_p1":"Sharif Capital is our specialized business brokerage branch connecting entrepreneurs and serious investors with solid commercial opportunities in Dubai and the GCC region.","c3_p2":"We also help global business owners set up new companies, open corporate bank accounts, and structure joint business ventures with complete confidentiality."}},"founder":{"en":{"name":"Ali Sharif","title":"CEO \\\\u0026amp; Founder, Sharif Group","badge":"A MESSAGE FROM OUR FOUNDER","quote":"A future where happy clients, positive community impact, and continuous progress guide everything we do.","p1":"As the founder of Sharif Group, I, Ali Sharif, started this journey with a clear goal: to build real value for our clients and trusted partners. Today, with our hard-working team, we are proud to set high standards in second citizenship and global investment advisory.","p2":"Over the past few years, our growth has been driven by honest effort and commitment. We have expanded our reach internationally, opening dedicated office hubs in both Dubai and London to serve our clients seamlessly.","photo":"alisharif.webp","profile_link":"https://sharifgroup.ae/ali-sharif/"}},"cta":{"en":{"badge":"EXECUTIVE ADVISORY DESK","heading":"Schedule Your Expert Consultation Today","desc":"Connect directly with our registered advisors at 116, The Binary Tower, Business Bay, Dubai to initialize your pre-vetting sequence.","btn_text":"Request Executive Briefing","btn_link":"../contact/index.html"}}}', NOW(), NOW())
