INSERT INTO cms_content (content_key, draft_data, live_data, updated_at, published_at) VALUES
('sgcms_cookiepolicy', '{"en":{"hero_badge":"DIGITAL GOVERNANCE \\\\u0026amp; TRACKING","hero_title":"Cookie Policy \\\\u0026amp; Privacy Controls","hero_desc":"Transparency, sovereignty, and data integrity regarding how Sharif Group uses cookies and similar technologies across our advisory platforms.","p1_title":"1. What Are Cookies?","p1_desc":"Cookies are small data files placed on your device to ensure security, maintain session integrity, and personalize your digital advisory experience.","p2_title":"2. How We Use Cookies","p2_desc":"We use strictly necessary cookies for administrative security and analytics cookies to optimize client mobility portal performance."}}', '{"en":{"hero_badge":"DIGITAL GOVERNANCE \\\\u0026amp; TRACKING","hero_title":"Cookie Policy \\\\u0026amp; Privacy Controls","hero_desc":"Transparency, sovereignty, and data integrity regarding how Sharif Group uses cookies and similar technologies across our advisory platforms.","p1_title":"1. What Are Cookies?","p1_desc":"Cookies are small data files placed on your device to ensure security, maintain session integrity, and personalize your digital advisory experience.","p2_title":"2. How We Use Cookies","p2_desc":"We use strictly necessary cookies for administrative security and analytics cookies to optimize client mobility portal performance."}}', NOW(), NOW())
